#include <atomic>
#include <cstdint>
#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

int main() {
    int k = 0;
    int n = 0;
    std::cin >> k >> n;
    std::mutex m;
    int64_t locked = 0;
    std::atomic<int64_t> counted{0};

    std::vector<std::thread> handlers;
    for (int i = 0; i < k; ++i) {
        handlers.emplace_back([&m, &locked, &counted, n] {
            for (int j = 0; j < n; ++j) {
                std::lock_guard<std::mutex> lock(m);
                ++locked;
            }
            for (int j = 0; j < n; ++j) {
                counted.fetch_add(1, std::memory_order_relaxed);
            }
        });
    }
    for (std::thread& t : handlers) {
        t.join();
    }
    std::cout << "mutex " << locked << '\n';
    std::cout << "atomic " << counted.load() << '\n';
    return 0;
}

