#include <atomic>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <thread>

struct Snapshot {  // plain fields, no atomics inside
    double spot;
    double vol;
    double rate;
};

int main() {
    Snapshot input{};
    std::cin >> input.spot >> input.vol >> input.rate;

    Snapshot snap{};
    std::atomic<bool> ready{false};
    double forward = 0.0;
    double daily_move = 0.0;

    std::thread pricer([&] {
        snap = input;                                  // 1. write the data
        ready.store(true, std::memory_order_release);  // 2. then flip the flag
    });
    std::thread strategy([&] {
        while (!ready.load(std::memory_order_acquire)) {
            // spin until the snapshot is published
        }
        forward = snap.spot * std::exp(snap.rate * 0.25);      // 3-month forward
        daily_move = snap.spot * snap.vol / std::sqrt(252.0);  // one-day move
    });
    pricer.join();
    strategy.join();
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "forward " << forward << '\n';
    std::cout << "daily move " << daily_move << '\n';
    return 0;
}

