    int64_t loss_limit = 0;
    int n = 0;
    std::cin >> k >> loss_limit >> n;
    std::vector<int64_t> pnl(n);  // marked P&L in dollars, one per tick
    for (int64_t& p : pnl) {
        std::cin >> p;
    }

    std::atomic<int64_t> high_water{pnl[0]};
    std::atomic<bool> killed{false};
    std::atomic<int> kill_claims{0};
    std::vector<std::thread> workers;
    for (int i = 0; i < k; ++i) {
        workers.emplace_back([&, i] {
